import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-138: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short138', durationInSeconds: 33.8, fps: 30, width: 1080, height: 1920 };

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', gap: 24, fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short138: React.FC = () => {
  const frame = useCurrentFrame();
  const CTA = secToFrame(29.5);
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  const lines = [{text: "FABLE 5.2 BATCH"}, {text: "= OPUS 5.5", accent: true}];
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={secToFrame(4.4)}>
        <CoverImage src="projects/short-138/cover.png" out={secToFrame(4.4) - 10} />
        <HookTitle hold onDark kicker="CLAUDE API" lines={lines} />
      </FadeOut>
      <FadeOut at={secToFrame(10.8)}>
        <ToolCard name="Fable 5.2 on Batch" tagline="Half off, async." chip="$4/$20" at={secToFrame(4.4) - 2}>
          <Panel>
            <Line k="input /1M" v="$4" good />
            <Line k="output /1M" v="$20" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(16.0)}>
        <ToolCard name="Opus 5.5 standard" tagline="Full price." chip="$4/$20" at={secToFrame(10.8) - 2}>
          <Panel>
            <Line k="input /1M" v="$4" good />
            <Line k="output /1M" v="$20" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(22.2)}>
        <ToolCard name="Identical" tagline="Batch can wait." chip="SAME" at={secToFrame(16.0) - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="Fable 5.2 Batch" v="$4 / $20" />
            <Line k="Opus 5.5" v="$4 / $20" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(25.7)}>
        <ToolCard name="Fable 5.2 standard" tagline="No discount." chip="$8/$40" at={secToFrame(22.2) - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="input /1M" v="$8" bad />
            <Line k="output /1M" v="$40" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="If it can wait" tagline="Top model, Opus price." chip="$4" at={secToFrame(25.7) - 2}>
          <Panel>
            <Line k="Batch Fable" v="$4 / $20" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-138/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="CLAUDE API" lines={lines} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Fable batch: $4. Same as Opus.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short138;
